<style>
*, *::before, *::after { margin: 0; padding: 0; box-sizing: border-box; }

:root {
  --bg: #000000;
  --bg-card: #1a1a1a;
  --bg-elevated: #232323;
  --red: #E50914;
  --red-hover: #f6121d;
  --white: #FFFFFF;
  --gray: #8c8c8c;
  --gray-light: #b3b3b3;
  --border: #333333;
  --font: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  --max-w: 1200px;
}

html { scroll-behavior: smooth; }

body {
  font-family: var(--font);
  background: var(--bg);
  color: var(--white);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

a { color: inherit; text-decoration: none; }

/* ── HEADER ── */
.header {
  position: absolute;
  top: 0; left: 0; right: 0;
  z-index: 100;
  padding: 20px 4%;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.logo {
  font-size: 1.8rem;
  font-weight: 900;
  color: var(--red);
  letter-spacing: -0.5px;
  text-transform: uppercase;
}

.header-right {
  display: flex;
  align-items: center;
  gap: 16px;
}

.lang-select {
  background: transparent;
  color: var(--white);
  border: 1px solid var(--border);
  border-radius: 4px;
  padding: 4px 12px;
  font-size: 0.85rem;
  font-family: var(--font);
  cursor: pointer;
}
.lang-select option { background: var(--bg); }

.btn-signin {
  background: var(--red);
  color: var(--white);
  border: none;
  border-radius: 4px;
  padding: 6px 16px;
  font-size: 0.9rem;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.2s;
  font-family: var(--font);
}
.btn-signin:hover { background: var(--red-hover); }

/* ── HERO ── */
.hero {
  position: relative;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: 120px 4% 80px;
  overflow: hidden;
}

.hero-bg {
  position: absolute;
  inset: 0;
  background:
    linear-gradient(to top, var(--bg) 0%, transparent 40%),
    linear-gradient(to bottom, rgba(0,0,0,0.7) 0%, transparent 30%),
    linear-gradient(135deg,
