  background-size: cover;
}

.hero-mosaic {
  position: absolute;
  inset: 0;
  opacity: 0.12;
  display: grid;
  grid-template-columns: repeat(8, 1fr);
  grid-template-rows: repeat(4, 1fr);
  gap: 6px;
  transform: rotate(-12deg) scale(1.4);
  transform-origin: center;
}

.mosaic-tile {
  border-radius: 6px;
  background: linear-gradient(135deg, #2a2a2a, #1a1a1a);
}
.mosaic-tile:nth-child(odd) { background: linear-gradient(135deg, #3a1a1e, #1a0a0e); }

.hero-content {
  position: relative;
  z-index: 2;
  max-width: 740px;
}

.hero h1 {
  font-size: clamp(2rem, 5vw, 3.2rem);
  font-weight: 900;
  line-height: 1.1;
  margin-bottom: 16px;
}

.hero .subtitle {
  font-size: clamp(1.1rem, 2vw, 1.4rem);
  font-weight: 400;
  margin-bottom: 24px;
}

.hero .prompt {
  font-size: clamp(0.95rem, 1.5vw, 1.15rem);
  color: var(--gray-light);
  margin-bottom: 20px;
}

.email-form {
  display: flex;
  gap: 0;
  max-width: 600px;
  margin: 0 auto;
}

.email-form input {
  flex: 1;
  min-width: 0;
  padding: 14px 16px;
  font-size: 1rem;
  font-family: var(--font);
  border: 1px solid var(--border);
  border-right: none;
  border-radius: 4px 0 0 4px;
  background: rgba(22,22,22,0.8);
  color: var(--white);
  outline: none;
  transition: border-color 0.2s;
}
.email-form input::placeholder { color: var(--gray); }
.email-form input:focus { border-color: var(--white); }

.btn-cta {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: var(--red);
  color: var(--white);
  border: none;
  border-radius: 0 4px 4px 0;
  padding: 14px 28px;
  font-size: 1.1rem;
  font-weight: 700;
  cursor: pointer;
  white-space: nowrap;
  font-family: var(--font);
  transition: background 0.2s;
}
.btn-cta:hover { background: var(--red-hover); }

/* ── SECTION DIVIDER ── */
