  font-weight: 800;
  margin-bottom: 24px;
  max-width: var(--max-w);
  margin-left: auto;
  margin-right: auto;
}

.carousel-wrapper {
  position: relative;
  max-width: var(--max-w);
  margin: 0 auto;
}

.carousel {
  display: flex;
  gap: 12px;
  overflow-x: auto;
  scroll-behavior: smooth;
  scrollbar-width: none;
  -ms-overflow-style: none;
  padding-bottom: 10px;
  -webkit-overflow-scrolling: touch;
}
.carousel::-webkit-scrollbar { display: none; }

.carousel-card {
  flex: 0 0 180px;
  position: relative;
  border-radius: 6px;
  overflow: hidden;
  cursor: pointer;
  transition: transform 0.3s;
}
.carousel-card:hover { transform: scale(1.05); }

.card-poster {
  width: 100%;
  aspect-ratio: 2/3;
  display: flex;
  align-items: flex-end;
  padding: 12px;
  position: relative;
}

.card-poster .poster-bg {
  position: absolute;
  inset: 0;
  border-radius: 6px;
}

.rank-number {
  position: absolute;
  left: -4px;
  bottom: -10px;
  font-size: 7rem;
  font-weight: 900;
  line-height: 1;
  color: transparent;
  -webkit-text-stroke: 3px var(--gray);
  text-shadow: none;
  z-index: 1;
  pointer-events: none;
}

.card-title {
  position: relative;
  z-index: 2;
  font-size: 0.85rem;
  font-weight: 700;
  padding-left: 40px;
  text-shadow: 0 1px 6px rgba(0,0,0,0.9);
}

.carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 44px;
  height: 80px;
  background: rgba(20,20,20,0.7);
  border: none;
  color: var(--white);
  font-size: 1.5rem;
  cursor: pointer;
  z-index: 5;
  border-radius: 4px;
  transition: background 0.2s;
  display: flex;
  align-items: center;
  justify-content: center;
}
.carousel-btn:hover { background: rgba(40,40,40,0.9); }
.carousel-btn.left { left: 0; }
.carousel-btn.right { right: 0; }

/* ── FEATURES ── */
.features {
  padding: 60px 4%;
