  color: var(--gray-light);
  line-height: 1.5;
}

.feature-icon {
  align-self: flex-end;
  margin-top: 20px;
  width: 48px;
  height: 48px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.6rem;
}

/* ── FAQ ── */
.faq {
  padding: 60px 4%;
}

.faq h2 {
  font-size: clamp(1.4rem, 3vw, 1.8rem);
  font-weight: 800;
  margin-bottom: 24px;
  text-align: center;
}

.faq-list {
  max-width: 800px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.faq-item {
  background: var(--bg-card);
  border-radius: 4px;
  overflow: hidden;
}

.faq-question {
  width: 100%;
  background: var(--bg-elevated);
  border: none;
  color: var(--white);
  padding: 20px 24px;
  font-size: 1.1rem;
  font-weight: 600;
  font-family: var(--font);
  text-align: left;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: space-between;
  transition: background 0.2s;
}
.faq-question:hover { background: #2e2e2e; }

.faq-icon {
  font-size: 1.6rem;
  font-weight: 300;
  transition: transform 0.3s;
  flex-shrink: 0;
  margin-left: 16px;
}
.faq-item.active .faq-icon { transform: rotate(45deg); }

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.4s ease, padding 0.4s ease;
}

.faq-answer-inner {
  padding: 20px 24px;
  font-size: 1rem;
  color: var(--gray-light);
  line-height: 1.7;
}

.faq-item.active .faq-answer {
  max-height: 400px;
}

/* ── BOTTOM CTA ── */
.bottom-cta {
  padding: 60px 4%;
  text-align: center;
}

.bottom-cta .prompt {
  font-size: clamp(1.1rem, 2vw, 1.3rem);
  margin-bottom: 20px;
  color: var(--gray-light);
}

.bottom-cta .email-form {
  max-width: 600px;
  margin: 0 auto;
}

/* ── FOOTER ── */
.footer {
  padding: 60px 4% 40px;
  border-top: 1px solid var(--border);
  max-width: var(--max-w);
  margin: 0 auto;
}

.footer .contact-prompt {
  color: var(--gray);
  margin-bottom: 30px;
  font-size: 0.95rem;
}
.footer .contact-prompt a { text-decoration: underline; }

.footer-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px 20px;
  margin-bottom: 30px;
}

.footer-grid a {
  font-size: 0.85rem;
  color: var(--gray);
  transition: color 0.2s;
  display: block;
  padding: 4px 0;
}
.footer-grid a:hover { color: var(--white); text-decoration: underline; }

.footer-bottom {
  display: flex;
  align-items: center;
  gap: 16px;
  flex-wrap: wrap;
}

.footer .legal-note {
  font-size: 0.75rem;
  color: #555;
  margin-top: 20px;
}

/* ── RESPONSIVE ── */
@media (max-width: 1024px) {
  .features-grid { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 768px) {
  .header { padding: 16px 4%; }
  .logo { font-size: 1.4rem; }

  .hero { min-height: 80vh; padding: 100px 4% 60px; }
  .hero h1 { font-size: 1.8rem; }

  .email-form { flex-direction: column; }
  .email-form input {
    border-right: 1px solid var(--border);
    border-radius: 4px;
    margin-bottom: 10px;
  }
  .btn-cta { border-radius: 4px; justify-content: center; }

  .features-grid { grid-template-columns: 1fr; }

  .footer-grid { grid-template-columns: repeat(2, 1fr); }

  .carousel-card { flex: 0 0 150px; }
  .rank-number { font-size: 5rem; }
}

@media (max-width: 480px) {
  .carousel-card { flex: 0 0 130px; }
  .rank-number { font-size: 4.5rem; }
  .carousel-btn { width: 36px; height: 60px; font-size: 1.2rem; }
}
</style>
